def _check_pos_int(name, value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{name} must be an int, got {type(value).__name__}")
    if value <= 0:
        raise ValueError(f"{name} must be positive, got {value}")


def kv_cache_bytes(n_layers, n_kv_heads, head_dim, seq_len, batch=1, bytes_per_elem=2):
    """Bytes of K and V cache for `batch` sequences of `seq_len` tokens."""
    for name, value in (("n_layers", n_layers), ("n_kv_heads", n_kv_heads),
                        ("head_dim", head_dim), ("seq_len", seq_len),
                        ("batch", batch), ("bytes_per_elem", bytes_per_elem)):
        _check_pos_int(name, value)
    # factor 2 = one tensor for keys, one for values
    return 2 * n_layers * n_kv_heads * head_dim * seq_len * batch * bytes_per_elem


def max_concurrent_sequences(total_bytes, weight_bytes, reserve_bytes,
                             n_layers, n_kv_heads, head_dim, seq_len,
                             bytes_per_elem=2):
    """How many full-length sequences fit after weights and a fixed reserve."""
    for name, value in (("total_bytes", total_bytes), ("weight_bytes", weight_bytes)):
        _check_pos_int(name, value)
    if isinstance(reserve_bytes, bool) or not isinstance(reserve_bytes, int):
        raise TypeError("reserve_bytes must be an int")
    if reserve_bytes < 0:
        raise ValueError("reserve_bytes must be non-negative")
    usable = total_bytes - weight_bytes - reserve_bytes
    if usable < 0:
        raise ValueError("weights plus reserve exceed total memory")
    per_seq = kv_cache_bytes(n_layers, n_kv_heads, head_dim, seq_len, 1, bytes_per_elem)
    return usable // per_seq
```

Usage sketch for the scenario (checked by the tests below): kv_cache_bytes(32, 32, 128, 4096) == 2 * 2**30; max_concurrent_sequences(80 * 2**30, 14 * 10**9, 6 * 2**30, 32, 32, 128, 4096) == 30 and the same call with n_kv_heads=8 returns 121. Changing bytes_per_elem to 1 (an 8-bit cache) doubles the 8-head result to roughly 243 before any quality check, because the per-sequence cost halves.

